def test_empty_input_gives_empty_list() -> None:
    assert validate_rows([]) == []


def test_zero_and_negative_closes_are_dropped() -> None:
    rows = [
        RawRow("2024-01-02", "A", 0.0),
        RawRow("2024-01-02", "B", -3.0),
        RawRow("2024-01-02", "C", 0.5),
    ]
    assert validate_rows(rows) == [RawRow("2024-01-02", "C", 0.5)]


def test_later_duplicate_in_file_order_wins() -> None:
    rows = [
        RawRow("2024-01-02", "A", 1.0),
        RawRow("2024-01-02", "A", 2.0),
        RawRow("2024-01-02", "A", 3.0),
    ]
    assert validate_rows(rows) == [RawRow("2024-01-02", "A", 3.0)]


def test_unusable_later_duplicate_does_not_replace_usable_one() -> None:
    rows = [
        RawRow("2024-01-02", "A", 1.0),
        RawRow("2024-01-02", "A", None),
        RawRow("2024-01-02", "A", -1.0),
    ]
    assert validate_rows(rows) == [RawRow("2024-01-02", "A", 1.0)]


def test_requested_tickers_all_present_pass() -> None:
    rows = [RawRow("2024-01-02", "A", 1.0), RawRow("2024-01-02", "B", 2.0)]
    assert len(validate_rows(rows, ["A", "B"])) == 2


def test_ticker_with_only_nonpositive_closes_is_a_key_error() -> None:
    rows = [RawRow("2024-01-02", "A", 1.0), RawRow("2024-01-02", "B", 0.0)]
    with pytest.raises(KeyError, match="B"):
        validate_rows(rows, ["A", "B"])

